import React from 'react'

function Cart({allData}) {
  return (
    <div>
        {allData.map(function (item) {
                return item.id>2 ?  (
                    <div key={item.id}>
                        <h2>My Name is {item.firstName} {item.lastName} </h2>
                        <h2>My Color is {item.color} </h2>
                        <h5>My ID is {item.id} </h5>
                        <hr></hr>
                    </div>
                ): item.id==1?(
                    <div>
                        <h1>Hii</h1>
                    </div>
                ):(
                    <div>
                        <h5>Not In Range</h5>
                    </div>
                )
            
        })}
    </div>
  )
}

export default Cart